// Package config assembles the settings for a client connection.
//
// Every setting is optional. Callers build a [Config] with [New], naming only
// the settings that differ from the defaults:
//
//	cfg, err := config.New(
//		config.WithAddr("db.internal:5432"),
//		config.WithTimeout(5*time.Second),
//	)
//	if err != nil {
//		return err
//	}
package config

import (
	"errors"
	"fmt"
	"io"
	"log/slog"
	"maps"
	"time"
)

// Defaults applied by [New] before any [Option] runs.
const (
	DefaultAddr       = "localhost:8080"
	DefaultTimeout    = 30 * time.Second
	DefaultMaxRetries = 3
)

// ErrInvalid is returned by [New] when the resolved settings are not usable.
// Wrapped errors describe the offending setting.
var ErrInvalid = errors.New("invalid config")

// Config holds the settings resolved by [New]. Treat a Config as read-only
// once constructed; in particular, do not mutate Metadata.
type Config struct {
	// Addr is the "host:port" address of the server.
	Addr string

	// Timeout bounds a single request. It is always greater than zero.
	Timeout time.Duration

	// MaxRetries is the number of retries after a failed request. Zero
	// disables retries.
	MaxRetries int

	// Compression reports whether requests are compressed on the wire.
	Compression bool

	// Logger receives operational logs. It is never nil; by default it
	// discards everything.
	Logger *slog.Logger

	// Metadata is sent with every request. It is never nil, and it is a copy
	// of whatever the caller passed to [WithMetadata].
	Metadata map[string]string
}

// New returns a Config built from the defaults and the given options, applied
// in order, so a repeated option wins with its last occurrence. The defaults
// are [DefaultAddr], [DefaultTimeout] and [DefaultMaxRetries], compression
// disabled, a logger that discards output, and empty metadata.
//
// New validates the combined result and wraps [ErrInvalid] if it is unusable.
func New(opts ...Option) (Config, error) {
	cfg := Config{
		Addr:       DefaultAddr,
		Timeout:    DefaultTimeout,
		MaxRetries: DefaultMaxRetries,
		Logger:     slog.New(slog.NewTextHandler(io.Discard, nil)),
		Metadata:   map[string]string{},
	}

	for _, o := range opts {
		o.apply(&cfg)
	}

	if cfg.Addr == "" {
		return Config{}, fmt.Errorf("%w: empty addr", ErrInvalid)
	}
	if cfg.Timeout <= 0 {
		return Config{}, fmt.Errorf("%w: timeout %v must be positive", ErrInvalid, cfg.Timeout)
	}
	if cfg.MaxRetries < 0 {
		return Config{}, fmt.Errorf("%w: max retries %d must not be negative", ErrInvalid, cfg.MaxRetries)
	}
	return cfg, nil
}

// An Option overrides a single setting in a [Config].
type Option interface {
	apply(*Config)
}

type addrOption string

func (a addrOption) apply(cfg *Config) { cfg.Addr = string(a) }

// WithAddr sets the server address. An empty addr is rejected by [New].
func WithAddr(addr string) Option { return addrOption(addr) }

type timeoutOption time.Duration

func (t timeoutOption) apply(cfg *Config) { cfg.Timeout = time.Duration(t) }

// WithTimeout sets the per-request timeout. A non-positive timeout is rejected
// by [New]; there is no "unlimited" setting.
func WithTimeout(d time.Duration) Option { return timeoutOption(d) }

type maxRetriesOption int

func (m maxRetriesOption) apply(cfg *Config) { cfg.MaxRetries = int(m) }

// WithMaxRetries sets the retry count. Zero disables retries; a negative count
// is rejected by [New].
func WithMaxRetries(n int) Option { return maxRetriesOption(n) }

type compressionOption bool

func (c compressionOption) apply(cfg *Config) { cfg.Compression = bool(c) }

// WithCompression enables or disables wire compression.
func WithCompression(enabled bool) Option { return compressionOption(enabled) }

type loggerOption struct{ logger *slog.Logger }

func (l loggerOption) apply(cfg *Config) {
	if l.logger != nil {
		cfg.Logger = l.logger
	}
}

// WithLogger sets the logger. A nil logger leaves the discarding default in
// place, so [Config].Logger is always safe to call.
func WithLogger(logger *slog.Logger) Option { return loggerOption{logger: logger} }

type metadataOption struct{ metadata map[string]string }

func (m metadataOption) apply(cfg *Config) { cfg.Metadata = maps.Clone(m.metadata) }

// WithMetadata sets the metadata sent with every request, replacing any
// metadata set earlier. The map is copied, so later changes by the caller do
// not affect the [Config].
func WithMetadata(metadata map[string]string) Option {
	return metadataOption{metadata: maps.Clone(metadata)}
}
```

Note: `maps.Clone(nil)` returns nil, so `WithMetadata(nil)` yields a nil `Metadata`. If you'd rather keep the "never nil" guarantee absolute, change `apply` to fall back to an empty map when the clone is nil.

