```go
package config_test

import (
	"errors"
	"maps"
	"testing"
	"time"

	"example.com/config"
)

func TestNewDefaults(t *testing.T) {
	cfg, err := config.New()
	if err != nil {
		t.Fatalf("New() error = %v", err)
	}

	if cfg.Addr != config.DefaultAddr {
		t.Errorf("Addr = %q, want %q", cfg.Addr, config.DefaultAddr)
	}
	if cfg.Timeout != config.DefaultTimeout {
		t.Errorf("Timeout = %v, want %v", cfg.Timeout, config.DefaultTimeout)
	}
	if cfg.MaxRetries != config.DefaultMaxRetries {
		t.Errorf("MaxRetries = %d, want %d", cfg.MaxRetries, config.DefaultMaxRetries)
	}
	if cfg.Compression {
		t.Error("Compression = true, want false")
	}
	if cfg.Logger == nil {
		t.Error("Logger = nil, want non-nil")
	}
	if len(cfg.Metadata) != 0 {
		t.Errorf("Metadata = %v, want empty", cfg.Metadata)
	}
}

func TestNewOptions(t *testing.T) {
	tests := []struct {
		name string
		opts []config.Option
		want config.Config
	}{
		{
			name: "each setting overridden",
			opts: []config.Option{
				config.WithAddr("db.internal:5432"),
				config.WithTimeout(5 * time.Second),
				config.WithMaxRetries(0),
				config.WithCompression(true),
				config.WithMetadata(map[string]string{"tenant": "acme"}),
			},
			want: config.Config{
				Addr:        "db.internal:5432",
				Timeout:     5 * time.Second,
				MaxRetries:  0,
				Compression: true,
				Metadata:    map[string]string{"tenant": "acme"},
			},
		},
		{
			name: "last option wins",
			opts: []config.Option{config.WithAddr("first:1"), config.WithAddr("second:2")},
			want: config.Config{
				Addr:       "second:2",
				Timeout:    config.DefaultTimeout,
				MaxRetries: config.DefaultMaxRetries,
				Metadata:   map[string]string{},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			got, err := config.New(tt.opts...)
			if err != nil {
				t.Fatalf("New() error = %v", err)
			}
			if got.Addr != tt.want.Addr || got.Timeout != tt.want.Timeout ||
				got.MaxRetries != tt.want.MaxRetries || got.Compression != tt.want.Compression {
				t.Errorf("New() = %+v, want %+v", got, tt.want)
			}
			if !maps.Equal(got.Metadata, tt.want.Metadata) {
				t.Errorf("Metadata = %v, want %v", got.Metadata, tt.want.Metadata)
			}
		})
	}
}

func TestNewMetadataIsCopied(t *testing.T) {
	metadata := map[string]string{"tenant": "acme"}

	cfg, err := config.New(config.WithMetadata(metadata))
	if err != nil {
		t.Fatalf("New() error = %v", err)
	}
	metadata["tenant"] = "other"

	if got := cfg.Metadata["tenant"]; got != "acme" {
		t.Errorf("Metadata[tenant] = %q, want %q", got, "acme")
	}
}

func TestNewInvalid(t *testing.T) {
	tests := []struct {
		name string
		opt  config.Option
	}{
		{name: "empty addr", opt: config.WithAddr("")},
		{name: "zero timeout", opt: config.WithTimeout(0)},
		{name: "negative retries", opt: config.WithMaxRetries(-1)},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			if _, err := config.New(tt.opt); !errors.Is(err, config.ErrInvalid) {
				t.Errorf("New() error = %v, want %v", err, config.ErrInvalid)
			}
		})
	}
}
```

Design choices worth knowing:

- **Functional options over a plain `Config` literal.** With six independently optional settings in a public package, options let call sites name only what differs and keep `Timeout: 0` from silently meaning "no timeout". If this package is internal and callers usually set everything at once, a keyed `Config` literal plus `New(cfg Config)` would be less machinery — say the word and I'll swap it.
- **Exported `Option` interface with an unexported `apply`.** Callers can't add options, and the type set stays under your control; adding a seventh `With*` is purely additive.
- Defaults are applied first, options second, validation last, so interdependent checks see the final values.
