func ProcessOrder(ctx context.Context, order *Order, db *sql.DB) error {
	if order == nil {
		return errors.New("order is nil")
	}
	if order.Status != "pending" {
		return fmt.Errorf("order status is %s, expected pending", order.Status)
	}
	if len(order.Items) == 0 {
		return errors.New("order has no items")
	}

	total, err := orderTotal(order.Items)
	if err != nil {
		return err
	}
	if total <= 0 {
		return errors.New("order total must be positive")
	}

	order.Total = total
	order.Status = "confirmed"
	_, err = db.ExecContext(ctx,
		"UPDATE orders SET total=$1, status=$2 WHERE id=$3",
		total, order.Status, order.ID)
	if err != nil {
		return fmt.Errorf("update order: %w", err)
	}
	return nil
}

func orderTotal(items []Item) (float64, error) {
	var total float64
	for _, item := range items {
		if item.Price <= 0 {
			return 0, fmt.Errorf("invalid price for item %s", item.Name)
		}
		if item.Quantity <= 0 {
			return 0, fmt.Errorf("invalid quantity for item %s", item.Name)
		}
		total += item.Price * float64(item.Quantity)
	}
	return total, nil
}
