// Package config holds the tunable settings for a service client and turns a
// caller-supplied [Config] into a complete, validated one.
//
// Every field of [Config] is optional. Callers fill in only what differs from
// the defaults and pass the result to [New], which applies defaults, then the
// caller's settings, then validates the combination:
//
//	cfg, err := config.New(config.Config{
//		Addr:       "db.internal:5432",
//		MaxRetries: 3,
//	})
package config

import (
	"crypto/tls"
	"fmt"
	"io"
	"log/slog"
	"time"
)

// Defaults applied by [New] to fields left unset.
const (
	DefaultAddr          = "localhost:8080"
	DefaultTimeout       = 30 * time.Second
	DefaultMaxConns      = 16
	DefaultShutdownGrace = 5 * time.Second
)

// Config describes how a client connects to and talks to a server.
//
// All fields are optional; the zero Config is valid and yields the documented
// defaults. Each field documents what its zero value means. Timeout is a
// pointer because a zero duration is a meaningful setting ("no timeout") that
// differs from "unset".
type Config struct {
	// Addr is the "host:port" of the server. Empty means [DefaultAddr].
	Addr string

	// Timeout bounds a single request. Nil means [DefaultTimeout]; a zero
	// duration disables the timeout. Must not be negative.
	Timeout *time.Duration

	// MaxRetries is the number of retries after a failed request. Zero means
	// no retries. Must not be negative, and requires a non-zero Timeout so
	// that a stuck request cannot retry forever.
	MaxRetries int

	// MaxConns caps concurrent connections. Zero means [DefaultMaxConns].
	// Must not be negative.
	MaxConns int

	// Logger receives client diagnostics. Nil means logs are discarded.
	Logger *slog.Logger

	// TLS configures transport security. Nil means the connection is
	// plaintext.
	TLS *tls.Config
}

// New returns cfg with defaults filled in for every unset field, after
// checking that the result is usable. The returned Config has a non-nil
// Timeout and Logger, so callers can dereference both without further checks.
//
// New does not mutate the caller's cfg, and it does not copy the TLS config:
// callers must not modify a *tls.Config they have handed over.
func New(cfg Config) (Config, error) {
	cfg.applyDefaults()
	if err := cfg.validate(); err != nil {
		return Config{}, err
	}
	return cfg, nil
}

// Default returns the configuration used when no settings are supplied.
func Default() Config {
	var cfg Config
	cfg.applyDefaults()
	return cfg
}

func (c *Config) applyDefaults() {
	if c.Addr == "" {
		c.Addr = DefaultAddr
	}
	if c.Timeout == nil {
		d := DefaultTimeout
		c.Timeout = &d
	}
	if c.MaxConns == 0 {
		c.MaxConns = DefaultMaxConns
	}
	if c.Logger == nil {
		c.Logger = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
}

// validate reports the first problem with an already-defaulted Config.
func (c *Config) validate() error {
	switch {
	case *c.Timeout < 0:
		return fmt.Errorf("config: negative Timeout %v", *c.Timeout)
	case c.MaxRetries < 0:
		return fmt.Errorf("config: negative MaxRetries %d", c.MaxRetries)
	case c.MaxConns < 0:
		return fmt.Errorf("config: negative MaxConns %d", c.MaxConns)
	case c.MaxRetries > 0 && *c.Timeout == 0:
		return fmt.Errorf("config: MaxRetries %d requires a non-zero Timeout", c.MaxRetries)
	}
	return nil
}
```

