// Package config defines the optional settings for a service client and
// resolves them against defaults.
package config

import (
	"cmp"
	"errors"
	"fmt"
	"log/slog"
	"time"
)

// Defaults applied by [New] to fields left at their zero value.
const (
	defaultAddr       = "localhost:8080"
	defaultTimeout    = 30 * time.Second
	defaultMaxConns   = 100
	defaultMaxRetries = 3
	defaultUserAgent  = "go-client/1.0"
)

// A Config holds the settings for a client. Every field is optional: a zero
// value selects the documented default, so the zero Config is valid and
// New(Config{}) returns a fully populated default configuration.
type Config struct {
	// Connection:
	Addr     string        // optional; default: "localhost:8080"
	Timeout  time.Duration // optional; per-request timeout; default: 30s
	MaxConns int           // optional; default: 100

	// Behavior:
	MaxRetries int          // optional; attempts after the first; default: 3
	UserAgent  string       // optional; default: "go-client/1.0"
	Logger     *slog.Logger // optional; default: discards every record
}

// New returns cfg with each zero-valued field replaced by its default. It
// reports every invalid field in one joined error; the returned Config is
// meaningful only when the error is nil.
func New(cfg Config) (Config, error) {
	cfg.Addr = cmp.Or(cfg.Addr, defaultAddr)
	cfg.Timeout = cmp.Or(cfg.Timeout, defaultTimeout)
	cfg.MaxConns = cmp.Or(cfg.MaxConns, defaultMaxConns)
	cfg.MaxRetries = cmp.Or(cfg.MaxRetries, defaultMaxRetries)
	cfg.UserAgent = cmp.Or(cfg.UserAgent, defaultUserAgent)
	if cfg.Logger == nil {
		cfg.Logger = slog.New(slog.DiscardHandler)
	}

	if err := cfg.validate(); err != nil {
		return Config{}, err
	}
	return cfg, nil
}

func (c Config) validate() error {
	var errs []error
	if c.Timeout < 0 {
		errs = append(errs, fmt.Errorf("negative Timeout: %v", c.Timeout))
	}
	if c.MaxConns < 0 {
		errs = append(errs, fmt.Errorf("negative MaxConns: %d", c.MaxConns))
	}
	if c.MaxRetries < 0 {
		errs = append(errs, fmt.Errorf("negative MaxRetries: %d", c.MaxRetries))
	}
	return errors.Join(errs...)
}
```

